package catalog

import (
    "net/http"
    "github.com/gin-gonic/gin"
)

func NewGinOrders() *gin.Engine {
    router := gin.New()
    router.POST("/orders", func(c *gin.Context) {
        var input struct {
            Item string `json:"item" binding:"required"`
            Quantity int `json:"quantity" binding:"gte=1,lte=10"`
        }
        if err := c.ShouldBindJSON(&input); err != nil {
            c.JSON(http.StatusBadRequest, gin.H{"error": "invalid order"})
            return
        }
        c.JSON(http.StatusCreated, gin.H{"item": input.Item, "quantity": input.Quantity})
    })
    return router
}

package catalog

import (
    "context"
    "errors"
    "net/http"
    "github.com/gin-gonic/gin"
)

func NewGinLookup(lookup func(context.Context, string) (string, error)) *gin.Engine {
    router := gin.New()
    router.GET("/items/:id", func(c *gin.Context) {
        name, err := lookup(c.Request.Context(), c.Param("id"))
        switch {
        case errors.Is(err, context.Canceled):
            c.JSON(http.StatusRequestTimeout, gin.H{"error": "request canceled"})
        case errors.Is(err, context.DeadlineExceeded):
            c.JSON(http.StatusGatewayTimeout, gin.H{"error": "lookup deadline"})
        case err != nil:
            c.JSON(http.StatusBadGateway, gin.H{"error": "lookup failed"})
        default:
            c.JSON(http.StatusOK, gin.H{"name": name})
        }
    })
    return router
}

