import (
    "strconv"
    "testing"
    "github.com/stretchr/testify/assert"
    "github.com/stretchr/testify/require"
)

func TestParseQuantity(t *testing.T) {
    for _, tc := range []struct {
        name, input string
        want int
        invalid bool
    }{
        {"ordinary", "12", 12, false},
        {"zero", "0", 0, false},
        {"negative", "-1", -1, false},
        {"empty", "", 0, true},
        {"malformed", "two", 0, true},
    } {
        t.Run(tc.name, func(t *testing.T) {
            got, err := strconv.Atoi(tc.input)
            if tc.invalid {
                var parseError *strconv.NumError
                require.ErrorAs(t, err, &parseError)
                assert.ErrorIs(t, err, strconv.ErrSyntax)
                assert.Equal(t, tc.input, parseError.Num)
                return
            }
            require.NoError(t, err)
            assert.Equal(t, tc.want, got)
        })
    }
}

package catalog

import (
    "errors"
    "testing"
    "github.com/stretchr/testify/mock"
    "github.com/stretchr/testify/require"
)

type Store interface { Load(string) (string, error) }
type StoreMock struct { mock.Mock }
func (s *StoreMock) Load(key string) (string, error) {
    args := s.Called(key)
    return args.String(0), args.Error(1)
}

func LoadTwice(store Store, key string) (string, error) {
    value, err := store.Load(key)
    if err != nil { return store.Load(key) }
    return value, nil
}

func TestStoreRecovery(t *testing.T) {
    unavailable := errors.New("unavailable")
    store := new(StoreMock)
    store.On("Load", "profile").Return("", unavailable).Once()
    store.On("Load", "profile").Return("Ada", nil).Once()
    value, err := LoadTwice(store, "profile")
    require.NoError(t, err)
    require.Equal(t, "Ada", value)
    store.AssertExpectations(t)
}
